/**
 * MEMBER 2 - Fandom Content
 * Demo seeder for the Fandom Hub, News, Gallery, Video Player, Podcasts,
 * Discover feed and the Beginner Fan glossary.
 *
 * Run:  node database/seedContent.js     (or)  npm run seed:content
 *
 * Every `image_url` points at a bundled asset generated by
 * frontend/tool/generate_banner_art.py, so the app always renders real
 * artwork instead of placeholders.
 *
 * Safe to run multiple times - existing rows are refreshed, never duplicated.
 */

import "./db.js";
import { initContentSchema } from "./contentSchema.js";
import { all, get, run } from "./dbhelpers.js";

initContentSchema();

const IMG = "assets/images/content";
const FANDOM_IMG = "assets/images/fandoms";

/** ISO-ish date N days in the past, so "Latest Updates" is always fresh. */
function daysAgo(days, hour = 9) {
  const date = new Date(Date.now() - days * 86400000);
  date.setHours(hour, 0, 0, 0);
  return date.toISOString().slice(0, 19).replace("T", " ");
}

