// ---------------------------------------------------------------------------

async function existingCount() {
  const row = await get(`SELECT COUNT(*) AS total FROM content_items`);
  return row ? row.total : 0;
}

async function seedArticles() {
  for (const item of ARTICLES) {
    const id = await upsert(item);
    if (id) {
      await run(
        `UPDATE content_items SET content_type = ?, subtitle = ?, body = ?, source = ?,
           duration_seconds = 0, episode_number = NULL WHERE id = ?`,
        [item.type, item.subtitle ?? null, item.body ?? null, item.source ?? null, id]
      );
    }
  }
}

async function seedGalleries() {
  for (const gallery of GALLERIES) {
    const id = await upsert({ ...gallery, type: "gallery" });
    if (!id) continue;

    const total = await get(
      `SELECT COUNT(*) AS total FROM content_media WHERE content_id = ?`,
      [id]
    );
    if (total && total.total > 0) continue;

    const captions = gallery.captions || [];
    for (let index = 0; index < captions.length; index += 1) {
      const tile = `${IMG}/gallery_${String((index % 9) + 1).padStart(2, "0")}.jpg`;
      await run(
        `INSERT INTO content_media (content_id, media_type, url, caption, sort_order)
         VALUES (?, 'image', ?, ?, ?)`,
        [id, tile, captions[index], index]
      );
    }
  }
}

async function seedVideos() {
  for (const video of VIDEOS) {
    await upsert({ ...video, type: "video" });
  }
}

async function seedPodcasts() {
  for (const podcast of PODCASTS) {
    const id = await upsert({
      ...podcast,
      type: "podcast",
      seconds: podcast.duration,
    });
    if (id) {
      await run(
        `UPDATE content_items SET episode_number = ?, season = ? WHERE id = ?`,
        [podcast.episode ?? null, podcast.season ?? null, id]
      );
    }
  }
}

/** Inserts (or refreshes) one content row and returns its id. */
async function upsert(item) {
  const row = await get(`SELECT id FROM content_items WHERE title = ?`, [item.title]);

  const values = [
    item.fandom,
    item.hub ?? null,
    item.type ?? "news",
    item.title,
    item.subtitle ?? null,
    item.summary ?? null,
    item.body ?? null,
    item.image ?? null,
    item.media ?? null,
    item.duration ?? item.seconds ?? 0,
    item.author ?? null,
    item.source ?? null,
    item.tags ?? null,
    item.views ?? 0,
    item.likes ?? 0,
    item.comments ?? 0,
    item.featured ?? 0,
    daysAgo(item.daysAgo ?? 1),
  ];

  if (row) {
    await run(
      `UPDATE content_items SET
         fandom = ?, hub_slug = ?, content_type = ?, title = ?, subtitle = ?, summary = ?,
         body = ?, image_url = ?, media_url = ?, duration_seconds = ?, author = ?, source = ?,
         tags = ?, views_count = ?, likes_count = ?, comments_count = ?, is_featured = ?,
         published_at = ?
       WHERE id = ?`,
      [...values, row.id]
    );
    return row.id;
  }

  const result = await run(
    `INSERT INTO content_items
     (fandom, hub_slug, content_type, title, subtitle, summary, body, image_url, media_url,
      duration_seconds, author, source, tags, views_count, likes_count, comments_count,
      is_featured, published_at)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
    values
  );
  return result.lastID;
}

async function seedGlossary() {
  for (const [term, definition, fandom, category] of GLOSSARY) {
    await run(
      `INSERT OR IGNORE INTO glossary_terms (term, definition, fandom, category)
       VALUES (?, ?, ?, ?)`,
      [term, definition, fandom, category]
    );
  }
}

/**
 * Recent history + offline cache for the demo account, so the "Recently
 * viewed" and "Offline content" rows of the Home dashboard are never empty.
 */
async function seedDemoHistory() {
  const user = await get(
    `SELECT id FROM users WHERE email = 'emma@fandomverse.com' LIMIT 1`
  );
  if (!user) return;

  const demo = [
    ["news", "One Piece", 0],
    ["video", "Wano", 1],
    ["podcast", "Retrospective", 1],
    ["news", "speedrun", 0],
    ["gallery", "Cosplay", 1],
    ["deep_dive", "Timeline", 0],
  ];

  for (const [type, keyword, offline] of demo) {
    const item = await get(
      `SELECT id FROM content_items
       WHERE content_type = ? AND title LIKE ?
       ORDER BY id LIMIT 1`,
      [type, `%${keyword}%`]
    );
    if (!item) continue;

    await run(
      `INSERT INTO content_views (user_id, content_id, is_offline, progress, viewed_at)
       VALUES (?, ?, ?, ?, CURRENT_TIMESTAMP)
       ON CONFLICT (user_id, content_id) DO UPDATE SET
         is_offline = excluded.is_offline,
         viewed_at = CURRENT_TIMESTAMP`,
      [user.id, item.id, offline, offline ? 0.4 : 0.15]
    );
  }
}

async function refreshHubCounters() {
  const hubs = await all(`SELECT slug FROM fandom_hubs`);
  for (const hub of hubs) {
    const row = await get(
      `SELECT
         IFNULL(SUM(views_count), 0) AS views,
         COUNT(*) AS items
       FROM content_items WHERE hub_slug = ?`,
      [hub.slug]
    );
    if (!row) continue;
    await run(
      `UPDATE fandom_hubs
       SET posts_count = ?,
           followers_count = 1200 + (? / 40)
       WHERE slug = ?`,
      [row.items, row.views, hub.slug]
    );
  }
}

async function main() {
  console.log("MEMBER 2 - seeding Fandom Content data...");

  const before = await existingCount();
  console.log(`  existing content rows: ${before}`);

  await seedArticles();
  await seedGalleries();
  await seedVideos();
  await seedPodcasts();
  await seedGlossary();
  await refreshHubCounters();
  await seedDemoHistory();

  const after = await existingCount();
  const counts = await all(
    `SELECT content_type, COUNT(*) AS total FROM content_items GROUP BY content_type`
  );
  const media = await get(`SELECT COUNT(*) AS total FROM content_media`);
  const terms = await get(`SELECT COUNT(*) AS total FROM glossary_terms`);
  const views = await get(`SELECT COUNT(*) AS total FROM content_views`);

  console.log(`  content rows now: ${after}`);
  counts.forEach((c) => console.log(`    ${c.content_type}: ${c.total}`));
  console.log(`  gallery images : ${media ? media.total : 0}`);
  console.log(`  glossary terms : ${terms ? terms.total : 0}`);
  console.log(`  recent views   : ${views ? views.total : 0}`);
  console.log("Done.");
}

main().catch((error) => {
  console.error("Seed failed:", error);
  process.exitCode = 1;
});

export default main;
